def count_weekend_days_breakdown(year, month):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    dim = lengths[month - 1] + (1 if month == 2 and is_leap(year) else 0)
    def weekday_of_first(y, m):
        mm, yy = (m + 12, y - 1) if m < 3 else (m, y)
        k, j = yy % 100, yy // 100
        h = (1 + (13 * (mm + 1)) // 5 + k + k // 4 + j // 4 + 5 * j) % 7
        return (h + 5) % 7
    first_wd = weekday_of_first(year, month)
    full_weeks, remainder = divmod(dim, 7)
    sat = sun = full_weeks
    for offset in range(remainder):
        wd = (first_wd + offset) % 7
        if wd == 5:
            sat += 1
        elif wd == 6:
            sun += 1
    return (sat, sun)

