def is_balanced_outside_quotes(s):
    quote_count = 0
    depth = 0
    for ch in s:
        if ch == "'":
            quote_count += 1
            continue
        if quote_count % 2 == 1:
            continue
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

