def find_min_sum_subarray_of_size_k(lst, k):
    prefix = [0] * (len(lst) + 1)
    for i, val in enumerate(lst):
        prefix[i + 1] = prefix[i] + val
    return min(prefix[i + k] - prefix[i] for i in range(len(lst) - k + 1))
